     "opis": "HISTORYCZNY – bez wystąpień od 02.10.2026 (CARBOHUMIC przeszedł na pasma-z-przelacznikiem; wersja do powrotu: archiwum-wersji/carbohumic-v7-przed-poprawkami-2026-10-02.html). Trzy taby i trzy bloki wariantów (CARBOHUMIC)",
